def solve(g):
    g=np.array(g); H,W=g.shape
    out=np.zeros_like(g)
    # find crosses: center cell with 4 orthogonal neighbors all 3 (complete) or center 0
    crosses=[]
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v==3: continue
            arms=[(r-1,c),(r+1,c),(r,c-1),(r,c+1)]
            arm3=all(0<=ar<H and 0<=ac<W and g[ar][ac]==3 for ar,ac in arms)
            if arm3:
                crosses.append((r,c,int(v)))
                if v!=0:
                    out[r][c]=v
                    for ar,ac in arms: out[ar][ac]=3
    armsset={(ar,ac) for r,c,v in crosses for ar,ac in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]}
    zeroc=[(r,c) for r,c,v in crosses if v==0]
    zcols={c for r,c in zeroc}
    zrows={r for r,c in zeroc}
    centers={(r,c):v for r,c,v in crosses}
    colc=[(r,c,v) for r,c,v in crosses if v!=0]
    # vertical lines: full column, skip arm cells and other centers
    for r,c,v in colc:
        for rr in range(H):
            if (rr,c) in armsset: continue
            if (rr,c) in centers and centers[(rr,c)]!=v: continue  # foreign center? skip
            if out[rr][c]==0 or (rr,c) in centers:
                out[rr][c]=v
    # horizontal lines with stop at foreign arm/center, hole at zcols
    for r,c,v in colc:
        for dirn in (-1,1):
            cc=c+dirn
            while 0<=cc<W:
                if (r,cc) in armsset:
                    break
                if (r,cc) in centers and centers[(r,cc)]!=v:
                    break
                if cc in zcols:
                    cc+=dirn; continue
                out[r][cc]=v
                cc+=dirn
    # horizontal lines also get holes at zcols for the vertical? (vertical already placed; re-zero zcols for cells that came from horizontal)
    # zero-cross: zero column cells that were painted by horizontal lines (rows not of vertical origin)
    # easier: recompute - zero out zcol cells except where vertical line
    return out

